                          "type": "string",
                          "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                        },
                        "role": {
                          "type": "string",
                          "enum": [
                            "source"
                          ]
                        },
                        "source": {
                          "anyOf": [
                            {
                              "type": "object",
                              "additionalProperties": false,
                              "properties": {
                                "kind": {
                                  "type": "string",
                                  "enum": [
                                    "project_measurement"
                                  ]
                                },
                                "id": {
                                  "type": "string",
                                  "format": "uuid"
                                },
                                "revision": {
                                  "type": "integer",
                                  "minimum": 1
                                }
                              },
                              "required": [
                                "kind",
                                "id",
                                "revision"
                              ]
                            },
                            {
                              "type": "object",
                              "additionalProperties": false,
                              "properties": {
                                "kind": {
                                  "type": "string",
                                  "enum": [
                                    "space_measurement"
                                  ]
                                },
                                "id": {
                                  "type": "string",
                                  "format": "uuid"
                                },
                                "space_revision": {
                                  "type": "integer",
                                  "minimum": 1
                                }
                              },
                              "required": [
                                "kind",
                                "id",
                                "space_revision"
                              ]
                            }
                          ]
                        }
                      },
                      "required": [
                        "id",
                        "role",
                        "source"
                      ]
                    },
                    {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "id": {
                          "type": "string",
                          "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                        },
                        "role": {
                          "type": "string",
                          "enum": [
                            "decision",
                            "estimate"
                          ]
                        },
                        "value": {
                          "type": "number",
                          "minimum": -1000000000,
                          "maximum": 1000000000
                        },
                        "unit": {
                          "type": "string",
                          "enum": [
                            "mm",
                            "deg",
                            "scalar"
                          ]
                        },
                        "reason": {
                          "type": "string",
                          "minLength": 1,
                          "maxLength": 2000
                        }
                      },
                      "required": [
                        "id",
                        "role",
                        "value",
                        "unit",
                        "reason"
                      ]
                    },
                    {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "id": {
                          "type": "string",
                          "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                        },
                        "role": {
