                          ]
                        },
                        "operation": {
                          "type": "string",
                          "enum": [
                            "add_v1",
                            "subtract_v1",
                            "multiply_v1",
                            "divide_v1"
                          ]
                        },
                        "operands": {
                          "type": "array",
                          "minItems": 2,
                          "maxItems": 2,
                          "items": {
                            "type": "string",
                            "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                          }
                        },
                        "rounding": {
                          "type": "string",
                          "enum": [
                            "exact",
