                            "unknown"
                          ]
                        },
                        "unit": {
                          "type": "string",
                          "enum": [
                            "mm",
                            "deg",
                            "scalar"
                          ]
                        },
                        "reason": {
                          "type": "string",
                          "minLength": 1,
                          "maxLength": 2000
                        }
                      },
                      "required": [
                        "id",
                        "role",
                        "unit",
                        "reason"
                      ]
                    }
                  ]
                }
              },
              "outputs": {
                "type": "array",
                "minItems": 1,
                "maxItems": 64,
                "uniqueItems": true,
                "items": {
                  "type": "string",
                  "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                }
              }
            },
            "required": [
              "method",
              "nodes",
              "outputs"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "method": {
                "type": "string",
                "enum": [
                  "construction_parameters_v1"
                ]
              },
              "record_id": {
                "type": "string",
                "format": "uuid"
              },
              "revision": {
                "type": "integer",
                "minimum": 1,
                "maximum": 2147483647
              }
            },
            "required": [
              "method",
              "record_id",
              "revision"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "method": {
                "type": "string",
                "enum": [
                  "stair_study_v1"
                ]
              },
              "plan_id": {
                "type": "string",
                "format": "uuid"
              },
              "plan_revision": {
                "type": "integer",
                "minimum": 1,
                "maximum": 2147483647
              },
              "recipe": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "generator": {
                    "type": "string",
                    "enum": [
                      "stair_study_v1"
                    ]
                  },
                  "version": {
                    "type": "integer",
                    "enum": [
                      1
                    ]
                  },
                  "from_level_id": {
                    "type": "string"
                  },
                  "to_level_id": {
                    "type": "string"
                  },
                  "start_x_mm": {
                    "type": "number",
                    "description": "Centre of first riser, at lower floor; shared building x/east datum."
                  },
                  "start_y_mm": {
                    "type": "number",
                    "description": "Centre of first riser, shared building y/north datum."
                  },
                  "heading": {
                    "type": "string",
                    "enum": [
                      "north",
                      "east",
                      "south",
                      "west"
                    ]
                  },
                  "turn": {
                    "type": "string",
                    "enum": [
                      "straight",
                      "left",
                      "right"
                    ]
                  },
                  "risers": {
                    "type": "integer",
                    "minimum": 3,
                    "maximum": 60
                  },
                  "first_flight_risers": {
                    "type": [
                      "integer",
                      "null"
                    ],
                    "description": "Rises to square intermediate landing for a quarter turn; 2 through total-2. Null for straight."
                  },
                  "width_mm": {
                    "type": "integer",
                    "description": "Walking strip width, whole mm; no stringers/handrails added."
                  },
                  "going_mm": {
                    "type": "integer"
                  },
                  "landing_depth_mm": {
                    "type": "integer"
                  },
                  "opening": {
                    "type": [
                      "object",
                      "null"
                    ],
                    "additionalProperties": false,
                    "properties": {
                      "x_mm": {
                        "type": "number"
                      },
                      "y_mm": {
                        "type": "number"
                      },
                      "width_mm": {
                        "type": "number"
                      },
                      "depth_mm": {
                        "type": "number"
                      }
                    },
                    "required": [
                      "x_mm",
                      "y_mm",
                      "width_mm",
                      "depth_mm"
                    ],
                    "description": "Explicit rectangular floor-opening proposal. Null means unspecified, not a solid/empty floor. Inspect first for a conservative suggestion; do not remove slabs."
                  },
                  "required_headroom_mm": {
                    "type": "integer",
                    "description": "Explicit project study criterion, not an automatically determined legal standard."
                  },
                  "upper_ceiling_above_floor_mm": {
                    "type": [
                      "integer",
                      "null"
                    ],
                    "description": "Flat upper ceiling height above upper finished floor. Null if unknown; never infer it from slab thickness."
                  },
                  "basis": {
                    "type": "string",
                    "enum": [
                      "provided_spec",
                      "estimated"
                    ]
                  },
                  "source": {
                    "type": "string",
                    "description": "Identify actual supplied dimensions or explicit reversible design assumptions."
                  }
                },
                "required": [
                  "generator",
                  "version",
                  "from_level_id",
                  "to_level_id",
                  "start_x_mm",
                  "start_y_mm",
                  "heading",
                  "turn",
                  "risers",
                  "first_flight_risers",
                  "width_mm",
                  "going_mm",
                  "landing_depth_mm",
                  "opening",
                  "required_headroom_mm",
                  "upper_ceiling_above_floor_mm",
                  "basis",
                  "source"
                ]
              }
            },
            "required": [
              "method",
              "plan_id",
              "plan_revision",
              "recipe"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "method": {
                "type": "string",
                "enum": [
                  "saved_stair_study_v1"
                ]
              },
              "record_id": {
                "type": "string",
                "format": "uuid"
              },
              "revision": {
                "type": "integer",
                "minimum": 1,
                "maximum": 2147483647
              }
            },
            "required": [
              "method",
              "record_id",
              "revision"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "method": {
                "type": "string",
                "enum": [
                  "material_purchase_v1"
                ]
              },
              "requirement_id": {
                "type": "string",
                "format": "uuid"
              },
              "revision": {
                "type": "integer",
                "minimum": 1,
                "maximum": 2147483647
              }
            },
            "required": [
              "method",
              "requirement_id",
              "revision"
            ]
          },
          {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "method": {
                "type": "string",
                "enum": [
                  "pack_purchase_v1"
                ]
              },
              "article_id": {
                "type": "string",
                "format": "uuid"
              },
              "article_revision": {
                "type": "integer",
                "minimum": 1,
                "maximum": 2147483647
              },
              "needs": {
                "type": "array",
                "minItems": 1,
                "maxItems": 24,
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "id": {
                      "type": "string",
                      "format": "uuid"
                    },
                    "revision": {
                      "type": "integer",
                      "minimum": 1,
                      "maximum": 2147483647
                    }
                  },
                  "required": [
                    "id",
                    "revision"
                  ]
                }
              }
            },
            "required": [
