              "article_id",
              "article_revision",
              "needs"
            ]
          }
        ]
      }
    },
    "required": [
      "calculation"
    ]
  }
}$calculator_contract$::jsonb;
 policy jsonb:=$calculator_policy${"name":"calculate_project","description":"Execute traceable versioned calculations in code.","how_to":"Use exact authorised source IDs/revisions. Preview a declared graph/stair; reopen saved construction/stair/material versions to replay. Code returns values, units, rounding, provenance and source readiness. Save only through the existing domain writer and its receipt; retain manual quantities and unknown inputs honestly.","schema_version":1,"always_load":false,"preload_phases":[],"active":true}$calculator_policy$::jsonb;
 texts jsonb:=$calculator_text_patches$[
  {
    "key": "bob.contract",
    "append": "Use calculate_project."
  },
  {
    "key": "cad-designer.contract",
    "append": "Use calculate_project for arithmetic; preserve its versions, units, rounding and provenance."
  },
  {
    "key": "cad-research.contract",
    "append": "Use calculate_project for arithmetic; preserve its versions, units, rounding and provenance."
  },
  {
    "key": "cad-reviewer.contract",
    "append": "Use calculate_project for arithmetic; preserve its versions, units, rounding and provenance."
  },
  {
    "key": "plan-compiler.contract",
    "append": "Use calculate_project for arithmetic; preserve its versions, units, rounding and provenance."
  },
  {
    "key": "plan-reviewer.contract",
    "append": "Use calculate_project for arithmetic; preserve its versions, units, rounding and provenance."
  },
  {
    "key": "calculator.schema-phase",
    "content": "This is a bounded read-only calculation phase before your final structured response. Use calculate_project if this task requires arithmetic, checking a derived value or replaying a saved model. Supply exact source IDs/revisions or explicit proposed decision/estimate inputs. If no calculation is needed, finish this phase briefly. Do not save, produce final JSON or repeat calculations in prose. The server will close tools and request your original structured output with the exact code results. Unsupported methods, missing values and changed sources must remain explicit."
  }
]$calculator_text_patches$::jsonb;
 role_names jsonb:=$calculator_roles$["ask-bob","cad-designer","cad-research","cad-reviewer","plan-compiler","plan-reviewer"]$calculator_roles$::jsonb;
 patch jsonb; role_name text; prior shared.ai_prompt_versions; template shared.ai_prompt_versions;
 prompt_uuid uuid; version_uuid uuid; next_version integer; definition jsonb; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 if exists(select 1 from shared.ai_prompts where app='bob' and prompt_key='tools.calculate_project') then raise exception 'calculator_already_published';end if;
 select v.* into template from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.inspect_stair_options';
 if not found then raise exception 'calculator_template_missing';end if;
 insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind) values('bob','tools.calculate_project',policy->>'description',policy->>'description','','','tool_contract') returning id into prompt_uuid;
 definition:=template.definition||contract||jsonb_build_object('handler','calculate_project','required_parameters',contract#>'{parameters,required}','optional_parameters','[]'::jsonb,'additional_description',policy->>'how_to');
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prompt_uuid,1,'tool_contract',1,jsonb_build_object('publication','project-calculator-v1'),'',definition,template.flow,template.available_variables) returning id into version_uuid;
 activation:=jsonb_build_object('tools.calculate_project',version_uuid);
 insert into bob.tool_catalog(name,description,how_to,schema_version,always_load,preload_phases,active)
  values(policy->>'name',policy->>'description',policy->>'how_to',1,false,'{}',true);
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.tools' and p.definition_kind='tool_contract' for update of p;
 if not found then raise exception 'calculator_toolbox_missing';end if;
 definition:=prior.definition;
 definition:=jsonb_set(definition,'{catalog}',definition->'catalog'||jsonb_build_array(policy));
 definition:=jsonb_set(definition,'{contract_keys}',definition->'contract_keys'||jsonb_build_array('tools.calculate_project'));
 definition:=jsonb_set(definition,'{shelves}',definition->'shelves'||jsonb_build_array(jsonb_build_object('label','Calculations','tools',jsonb_build_array('calculate_project'))));
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','project-calculator-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('bob.tools',version_uuid);
 for patch in select value from jsonb_array_elements(texts) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=patch->>'key' for update of p;
  if not found then
   if patch->>'key'<>'calculator.schema-phase' then raise exception 'calculator_instruction_missing';end if;
   insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind) values('bob',patch->>'key','Bounded calculation phase','Calculator access before structured output','','','instruction_fragment') returning id into prompt_uuid;
   insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
    values(prompt_uuid,1,'instruction_fragment',1,jsonb_build_object('publication','project-calculator-v1'),patch->>'content','{}','', '[]'::jsonb) returning id into version_uuid;
  else
   select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
   insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
    values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','project-calculator-v1'),prior.content||E'\n\n'||(patch->>'append'),prior.definition,prior.flow,prior.available_variables) returning id into version_uuid;
  end if;
  activation:=activation||jsonb_build_object(patch->>'key',version_uuid);
 end loop;
 for role_name in select jsonb_array_elements_text(role_names) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='role.'||role_name and p.definition_kind='role' for update of p;
  if not found then raise exception 'calculator_role_missing';end if;
  definition:=jsonb_set(prior.definition,'{tool_keys}',prior.definition->'tool_keys'||jsonb_build_array('tools.calculate_project'));
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','project-calculator-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object('role.'||role_name,version_uuid);
 end loop;
 perform shared.activate_ai_catalog('bob',activation);
end $calculator_catalog$;
commit;
